      gap: 16px;
    }
    .kpi-card {
      border-radius: 12px;
      padding: 22px 20px;
      position: relative;
      overflow: hidden;
    }
    .kpi-card.blue   { background: linear-gradient(135deg, #1a3a5c 0%, #2a5298 100%); color: white; }
    .kpi-card.red    { background: linear-gradient(135deg, #c0392b 0%, #e63946 100%); color: white; }
    .kpi-card.green  { background: linear-gradient(135deg, #1a6b5a 0%, #2a9d8f 100%); color: white; }
    .kpi-card.amber  { background: linear-gradient(135deg, #b5621a 0%, #f4a261 100%); color: white; }
