    .kpi-card .kpi-desc  { font-size: 12px; opacity: 0.75; line-height: 1.4; margin-top: 6px; }
    .kpi-card .kpi-trend { font-size: 11px; margin-top: 8px; opacity: 0.85; font-weight: 600; }

    /* ── Section headings ─────────────────────────── */
    .section-header { margin-bottom: 28px; }
    .section-number {
      font-size: 11px;
      font-weight: 700;
