      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      padding: 11px 14px;
      text-align: left;
    }
    thead th.right { text-align: right; }
    tbody td { padding: 10px 14px; font-size: 14px; border-bottom: 1px solid #f0f1f3; }
    tbody tr:last-child td { border-bottom: none; }
    tbody tr:hover td { background: #f5f8ff; }
    tbody td.right { text-align: right; font-variant-numeric: tabular-nums; }
    tbody td.bold  { font-weight: 600; }

    /* Rate badges */
    .rate-bar-wrap { display: flex; align-items: center; gap: 8px; }
    .rate-bar {
      height: 6px; border-radius: 3px;
      background: var(--accent);
      flex-shrink: 0;
    }
    .rate-bar.green { background: var(--accent-green); }
    .rate-bar.blue  { background: var(--accent-blue); }

    .badge-pill {
      display: inline-block;
      padding: 2px 10px;
      border-radius: 12px;
      font-size: 12px;
      font-weight: 600;
    }
    .badge-danger  { background: #fde8ea; color: #c0392b; }
    .badge-success { background: #d6f5f0; color: #1a6b5a; }
    .badge-warning { background: #fef3e2; color: #b5621a; }

    /* ── Two-column grid ──────────────────────────── */
    .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
    @media (max-width: 760px) { .two-col { grid-template-columns: 1fr; } }

    /* ── Callout box ──────────────────────────────── */
    .callout {
      border-radius: 10px;
      padding: 18px 22px;
      margin: 16px 0;
      border-left: 4px solid;
      font-size: 14px;
      line-height: 1.6;
    }
    .callout.info    { background: #eef3fb; border-color: var(--accent-blue);  color: #1a3a5c; }
    .callout.warn    { background: #fef9ec; border-color: var(--accent-gold);  color: #5a3b00; }
    .callout.danger  { background: #fdf0f0; border-color: var(--accent);       color: #7d1a1a; }
    .callout.success { background: #eef8f6; border-color: var(--accent-green); color: #0d3b33; }
    .callout strong  { display: block; margin-bottom: 4px; font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; }

    /* ── TOC ──────────────────────────────────────── */
    .toc {
      background: var(--surface);
      border-radius: 12px;
      padding: 26px 28px;
      box-shadow: var(--shadow);
      margin: 32px 0;
    }
    .toc h2 { font-size: 16px; color: var(--text-muted); font-weight: 600; margin-bottom: 14px; border: none; padding: 0; }
    .toc ol { padding-left: 20px; }
    .toc li { margin: 8px 0; }
    .toc a  { color: var(--primary-light); text-decoration: none; font-size: 14px; font-weight: 500; }
    .toc a:hover { text-decoration: underline; }

    /* ── Limitations grid ─────────────────────────── */
    .limit-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; margin: 20px 0; }
    .limit-item {
      background: var(--surface);
      border-radius: 10px;
      padding: 18px 20px;
      box-shadow: var(--shadow);
      border-top: 3px solid var(--accent-gold);
    }
    .limit-item h4 { font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 6px; }
    .limit-item p  { font-size: 13px; color: var(--text-muted); line-height: 1.55; }

    /* ── Rec cards ────────────────────────────────── */
    .rec-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin: 20px 0; }
    .rec-card {
      background: var(--surface);
      border-radius: 10px;
      padding: 20px;
      box-shadow: var(--shadow);
      border-left: 4px solid var(--accent-blue);
    }
    .rec-card.priority-1 { border-color: var(--accent); }
    .rec-card.priority-2 { border-color: var(--accent-gold); }
    .rec-card.priority-3 { border-color: var(--accent-green); }
    .rec-card .rec-tag {
      font-size: 11px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 8px;
    }
    .rec-card h4 { font-size: 15px; font-weight: 700; color: var(--primary); margin-bottom: 6px; }
    .rec-card p  { font-size: 13px; color: var(--text-muted); line-height: 1.55; }

    /* ── Footer ───────────────────────────────────── */
    .report-footer {
      background: var(--primary);
      color: rgba(255,255,255,0.7);
      text-align: center;
      padding: 30px 24px;
      font-size: 13px;
      margin-top: 64px;
    }
    .report-footer strong { color: white; }

    /* ── Print ─────────────────────────────────────── */
    @media print {
      .report-header { background: #1a3a5c !important; -webkit-print-color-adjust: exact; }
      .kpi-card { -webkit-print-color-adjust: exact; }
    }
  </style>
</head>
